const fs=require('fs'),assert=require('assert/strict'),png=require('./scripts/png.cjs');const d='备份/20261102-side-reference-audit/',before=JSON.parse(fs.readFileSync(d+'before.json')),p=JSON.parse(fs.readFileSync(d+'candidate.json'));function world(c){const a=png.decode(Buffer.from(c.dataURL.split(',')[1],'base64')),r=c.placement||{x:0,y:0},out=new Uint8Array(36*36*4);for(let y=0;y<a.height;y++)for(let x=0;x<a.width;x++){const xx=x+r.x,yy=y+r.y;if(xx>=0&&xx<36&&yy>=0&&yy<36)out.set(a.data.subarray((y*a.width+x)*4,(y*a.width+x)*4+4),(yy*36+xx)*4);}return out;}
let checked=0;for(const ai of [1,2]){const source=world(before.layers[11].frameData['8_'+ai+'_2']);for(const fi of [0,1,3]){const target=world(before.layers[11].frameData['8_'+ai+'_'+fi]);for(let y=25;y<=31;y++)for(let x=0;x<36;x++){if(x>8&&x<23)continue;const sx=x<=8?x-1:x+1,expected=sx>=0&&sx<36?[...source.subarray((y*36+sx)*4,(y*36+sx)*4+4)]:[0,0,0,0],i=((y+(fi===3?1:0))*36+x)*4;assert.deepEqual([...target.subarray(i,i+4)],expected,'native reference mapping');checked++;}}}assert.deepEqual(world(p.layers[11].frameData['8_0_0']),world(p.layers[11].frameData['8_0_1']),'hold first two hair poses');for(const li of [11,191])assert.deepEqual(p.layers[li].frameData['8_0_2'],before.layers[li].frameData['8_0_2'],'user third frame');const v=JSON.parse(fs.readFileSync(d+'verification.json'));Object.assign(v,{nativeFrontBackTipMappingCheckedPixels:checked,nativeMotion:'phases 1/2 hold contracted tips; phase3 compressed and spread; phase4 contracted tips +1y',originalThirdFramePreserved:true,inventedFringeChangesRemoved:true,referenceDirectionsUnchanged:true});fs.writeFileSync(d+'verification.json',JSON.stringify(v,null,2));console.log('PASS exact existing front/back lower-tip mapping:',checked,'pixels');
(async()=>{const url='http://127.0.0.1:8765/api/project?id=draft-user-canvas-merged-1793608789349-dbd059d3';const latest=await fetch(url);assert.deepEqual(await latest.json(),before,'new user save, stop');const r=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':fs.readFileSync(d+'etag.txt','utf8').trim()},body:JSON.stringify(p)}),message=await r.text();assert(r.ok,r.status+' '+message);const back=await fetch(url),raw=await back.text();assert.deepEqual(JSON.parse(raw),p);fs.writeFileSync(d+'after.json',raw);Object.assign(v,{putStatus:r.status,getStatus:back.status,exactAPIReadback:true});fs.writeFileSync(d+'verification.json',JSON.stringify(v,null,2));fs.writeFileSync(d+'恢复说明.txt','本次仅改verification.json列出的6个待机侧面头发frameData。恢复时GET当前工程，比较after.json，仅对尚未被后续编辑的本次条目替换为before.json对应条目，以ETag校验PUT，禁止旧整稿覆盖。额外副本恢复已验证。\n参照当前工程正面、背面待机下半发梢的逐像素形变，外展/回收位移在924个参照像素上严格吻合。保留第3帧、身体、眼睛、手、其他方向、动作、元数据与4×100ms。\n12帧主画布/预览/PNG路径核对通过；GIF4帧及100ms时长解码核对通过；未操作网页。');console.log('PASS saved, API readback exact');})();
